INSERT OR REPLACE INTO products (id, name, category, description, price, tag, image_url, is_featured, is_active) VALUES ('2624982', 'Água (Jamaica) 300ml', 'Sucos', 'Refresque-se com o sabor vibrante e único da Água de Jamaica. Feita a partir das flores de hibisco, essa bebida oferece um aroma envolvente e uma cor intensa. Com propriedades antioxidantes e refrescantes, a Água de Jamaica é perfeita para hidratar e energizar. Experimente essa bebida exótica e deixe-se levar pelos sabores tropicais.', 9, '', 'https://storage.googleapis.com/prod-cardapio-web/uploads/item/image/2624982/202503261902_30MF_i.jpg', 0, 1);
INSERT OR REPLACE INTO products (id, name, category, description, price, tag, image_url, is_featured, is_active) VALUES ('2624983', 'Suco (Laranja) 300ml', 'Sucos', 'MacroVita \nMacrovita Easy| Néctar de Laranja \nA Macrovita combina o sabor fresco da laranja em um néctar cuidadosamente preparado, mantendo toda a qualidade que você já conhece. É uma bebida prática e deliciosa para seu dia a dia, sem adição de conservantes.', 9, '', 'https://storage.googleapis.com/prod-cardapio-web/uploads/item/image/2624983/1e6604e0Nectar-Laranja_001.png', 0, 1);
INSERT OR REPLACE INTO products (id, name, category, description, price, tag, image_url, is_featured, is_active) VALUES ('2624984', 'Suco (Butiá) 300ml', 'Sucos', 'Suco de Butiá: Uma magia de sabor tropical em cada gole! Feito com polpa fresca de butiá, fruta nativa da região, nosso suco é refrescante, nutritivo e cheio de vitaminas. Experimente essa deliciosa bebida natural e descubra todo o encanto do Butiá.', 9, '', 'https://storage.googleapis.com/prod-cardapio-web/uploads/item/image/2624984/2d6189b8WhatsApp_Image_2026-07-14_at_15.23.03.jpeg', 0, 1);
